/** Tianshu 3.0: all paths are anchored to an immutable observation, not each local tick. */
function decimal_kwh(mixed $value): array {
    $raw=trim((string)$value);
    if(!preg_match('/^(?:0|[1-9][0-9]{0,10})(?:\.([0-9]{1,6}))?$/D',$raw,$m))throw new AppError('电量须为非负十进制，最多6位小数；不接受科学计数或截断');
