    foreach($rows as $r){if(!(int)$r['usable']||($short&&in_array($r['tag']??'',['batch','gap'],true)))continue;$duration=((float)$r['ts']-(float)$r['start'])/3600;if($duration<=0||$r['ts']>$now)continue;$q=(float)($r['quality_weight']??(in_array($r['tag']??'',['batch','gap'],true)?.4:.7));$w=$q*exp(-$lambda*max(0,($now-$r['ts'])/3600))*(-expm1(-$lambda*$duration))/$lambda;$sum+=$w*(float)$r['energy']/$duration;$total+=$w;}
    return $total>0?$sum/$total:0.;
}
/** Exact calendar exposure in Shanghai; no synthetic hourly labels. */
function ts_exposure(float $start,float $end): array {
