function ts_curve(array $expert,float $origin,float $hours): float {if(isset($expert['components'])){$sum=0.;foreach($expert['components'] as $component)$sum+=$component['weight']*ts_curve($component['expert'],$origin,$hours);return max(0.,$sum);}if(isset($expert['theta'])){$x=ts_exposure($origin,$origin+$hours*3600);return max(0.,$x[0]*$expert['theta'][0]+$x[1]*$expert['theta'][1]+$x[2]*$expert['theta'][2]);}return max(0.,$expert['rate']*$hours);}
