function ts_schedule(array $a,float $now,array $o,int $count,?float $last): array {
    [$day,$start,$end]=bounds($now,$o);$run=$a['forecast_run']??null;$age=$run?max(0.,($now-$run['origin'])/3600):0.;$zero=$run&&$run['zero_guard']!==null?max(0.,$run['zero_guard']-$age):null;$risk=$zero===null?8.:max(0.,$zero-2.);$unc=8.;if($run){$delta=max(.5,.1*max(0.,$a['balance_lower']-$o['reserve_kwh']));for($h=.25;$h<=min(8.,72.-$age);$h+=.25)if(ts_upper($run,$age+$h)-ts_mean($run,$age+$h)>$delta){$unc=$h;break;}}
    $cover=$run?min(8.,max(0.,72.-$age)):8.;$change=$a['suspect']||$a['accelerated']?2.:8.;$need=min($cover,$risk,$unc,$change);$deadline=$now+$need*3600;$earliest=max($start,$now,$last===null?$start:$last+$o['min_gap_minutes']*60);$remaining=$o['max_queries']-$count;$status='feasible';$reasons=[];$next=min($deadline,$end-$o['min_gap_minutes']*60);
    if($now<$start){$next=$start;$status='outside_window';}elseif($now>=$end){$next=$start+86400;$status='outside_window';}elseif($remaining<=1){$next=$end;$status=$end>$deadline?'budget_constrained':'final_reserved';}elseif($next<$earliest){$next=$earliest<=$end-$o['min_gap_minutes']*60?$earliest:$end;$status='infeasible_due_to_min_gap';}else{$next=max($earliest,$next);$slots=(int)ceil(max(0.,$end-$now)/max(3600.,$need*3600));if($slots>$remaining){$status='budget_constrained';$reasons[]='INSUFFICIENT_REMAINING_SLOTS';}}
    if($remaining<=0){$next=null;$status='budget_exhausted';}$reasons[]=['risk'=>'RISK_DEADLINE','uncertainty'=>'UNCERTAINTY_DEADLINE','change'=>'CHANGE_CONFIRMATION','coverage'=>'COVERAGE_DEADLINE'][array_search(min($risk,$unc,$change,$cover),['risk'=>$risk,'uncertainty'=>$unc,'change'=>$change,'coverage'=>$cover],true)]??'COVERAGE_DEADLINE';
    return ['day'=>$day,'next'=>$next,'target'=>min($o['max_queries'],max(3,$count+1)),'status'=>$status,'risk_deadline'=>$deadline,'need_hours'=>$need,'remaining'=>$remaining,'deadlines_hours'=>['risk'=>$risk,'uncertainty'=>$unc,'change'=>$change,'coverage'=>$cover],'reasons'=>$reasons,'mode'=>'engineering_guard','forecast_status'=>$run&&72.-$age<2.?'insufficient_forecast_horizon':'within_horizon'];
}
